        LockResponse res = txnHandler.lock(req);
        txnHandler.abortTxn(new AbortTxnRequest(txnid));
    }
    // run and fail initiator
    Initiator initiator = Mockito.spy(new Initiator());
    initiator.setConf(conf);
    initiator.init(new AtomicBoolean(true));
    doThrow(new RuntimeException("This was thrown on purpose by testInitiatorFailure")).when(initiator).resolvePartition(any());
    initiator.run();
