    TxnStore mockedTxnHandler = Mockito.spy(txnHandler);
    TaskHandler mockedTaskHandler = Mockito.spy(new AbortedTxnCleaner(conf, mockedTxnHandler, metadataCache, false, mockedFSRemover));
    // Invoke runtime exception when calling markCleaned.
    Mockito.doAnswer(invocationOnMock -> {
        throw new RuntimeException("Testing retry");
    }).when(mockedFSRemover).clean(any());
    Cleaner cleaner = new Cleaner();
    cleaner.setConf(conf);
    cleaner.init(new AtomicBoolean(true));
    cleaner.setCleanupHandlers(Arrays.asList(mockedTaskHandler));
    cleaner.run();
    Mockito.verify(mockedTxnHandler, Mockito.times(1)).setCleanerRetryRetentionTimeOnError(any(CompactionInfo.class));
    ShowCompactResponse scr = txnHandler.showCompact(new ShowCompactRequest());
    Assert.assertEquals(1, scr.getCompactsSize());
    ShowCompactResponseElement scre = scr.getCompacts().get(0);
    Assert.assertTrue(scre.getDbname().equals(dbName) && scre.getTablename().equals(tableName) && (isPartitioned ? scre.getPartitionname().equals("ds=" + partName) : scre.getPartitionname() == null) && "ready for cleaning".equalsIgnoreCase(scre.getState()) && scre.getType() == CompactionType.ABORT_TXN_CLEANUP && scre.getErrorMessage().equalsIgnoreCase("Testing retry"));
    String whereClause = " WHERE \"CQ_DATABASE\" = '" + dbName + "' AND \"CQ_TABLE\" = '" + tableName + "' AND \"CQ_PARTITION\"" + (isPartitioned ? " = 'ds=" + partName + "'" : " IS NULL") + " AND \"CQ_TYPE\" = 'c' AND \"CQ_STATE\" = 'r'";
    String retryRetentionQuery = "SELECT \"CQ_RETRY_RETENTION\" FROM \"COMPACTION_QUEUE\" " + whereClause;
    Assert.assertEquals(Long.toString(MetastoreConf.getTimeVar(conf, MetastoreConf.ConfVars.HIVE_COMPACTOR_CLEANER_RETRY_RETENTION_TIME, TimeUnit.MILLISECONDS)), TestTxnDbUtil.queryToString(conf, retryRetentionQuery, false).replace("\n", "").trim());
}

