    addDeltaFileWithTxnComponents(t, null, 2, false);
    CompactionRequest cr = new CompactionRequest(dbName, tableName, CompactionType.MAJOR);
    txnHandler.compact(cr);
    // Run compaction
    startWorker();
    // Check if there is a one base file
