    HiveConf.setIntVar(conf, HiveConf.ConfVars.HIVE_COMPACTOR_ABORTEDTXN_THRESHOLD, 0);
    MetadataCache metadataCache = new MetadataCache(true);
    FSRemover mockedFSRemover = Mockito.spy(new FSRemover(conf, ReplChangeManager.getInstance(conf), metadataCache));
    TaskHandler mockedTaskHandler = Mockito.spy(new AbortedTxnCleaner(conf, txnHandler, metadataCache, false, mockedFSRemover));
    runInitiator(conf);
    // Initiator must not add anything to compaction_queue
    String compactionQueuePresence = "SELECT COUNT(*) FROM \"COMPACTION_QUEUE\" " + " WHERE \"CQ_DATABASE\" = '" + dbName + "' AND \"CQ_TABLE\" = '" + tableName + "' AND \"CQ_PARTITION\"" + (isPartitioned ? " = 'ds=" + partName + "'" : " IS NULL");
    Assert.assertEquals(0, TestTxnDbUtil.countQueryAgent(conf, compactionQueuePresence));
    Cleaner cleaner = new Cleaner();
    cleaner.setConf(conf);
    cleaner.init(new AtomicBoolean(true));
    cleaner.setCleanupHandlers(Arrays.asList(mockedTaskHandler));
    cleaner.run();
    Mockito.verify(mockedFSRemover, Mockito.times(1)).clean(any(CleanupRequest.class));
    Mockito.verify(mockedTaskHandler, Mockito.times(1)).getTasks(any(HiveConf.class));
    Assert.assertEquals(0, TestTxnDbUtil.countQueryAgent(conf, compactionQueuePresence));
    Assert.assertEquals(0, TestTxnDbUtil.countQueryAgent(conf, "SELECT COUNT(*) FROM \"COMPLETED_COMPACTIONS\" " + " WHERE \"CC_DATABASE\" = '" + dbName + "' AND \"CC_TABLE\" = '" + tableName + "' AND \"CC_PARTITION\"" + (isPartitioned ? " = 'ds=" + partName + "'" : " IS NULL")));
    Assert.assertEquals(1, TestTxnDbUtil.countQueryAgent(conf, "SELECT COUNT(*) FROM \"COMPLETED_TXN_COMPONENTS\" " + " WHERE \"CTC_DATABASE\" = '" + dbName + "' AND \"CTC_TABLE\" = '" + tableName + "' AND \"CTC_PARTITION\"" + (isPartitioned ? " = 'ds=" + partName + "'" : " IS NULL")));
    List<Path> directories = getDirectories(conf, t, null);
    // All aborted directories removed, hence 1 committed delta directory must be present
    Assert.assertEquals(1, directories.size());
}

